'use strict';
const F=FrontierCore;
FrontierWorld.apply(worlds,state.frontier.projects);
Object.assign(resourceInfo,{herb:{verb:'Pick',name:'Wild herbs',doing:'Picking wild herbs',time:1.2,item:'herbs',amount:2,color:'#a9c789'},ore:{verb:'Mine',name:'Copper ore',doing:'Mining copper',time:2.5,item:'ore',amount:2,color:'#dfa478'},shell:{verb:'Collect',name:'Tide shells',doing:'Collecting shells',time:1.1,item:'shells',amount:2,color:'#f2ceae'}});
const itemIcons={herbs:'seed',ore:'ore',shells:'shells',marks:'marks',turnips:'seed',moonbeans:'seed',seeds:'seed',moonSeeds:'seed',treats:'berries',tools:'tool',lantern:'crystals',harvested:'seed',crafted:'tool',visits:'map'};
const itemNames={berries:'Berries',wood:'Timber',fish:'Fish',crystals:'Moon crystals',herbs:'Wild herbs',ore:'Copper ore',shells:'Tide shells',marks:'Trail marks',turnips:'Sun turnips',moonbeans:'Moon beans',seeds:'Turnip seeds',moonSeeds:'Moon-bean seeds',treats:'Treats',tools:'Tool set',lantern:'Lantern',harvested:'Crops harvested',crafted:'Items crafted',visits:'New places found'};
const requestKindLabel={gather:'Gathering request',farm:'Growing request',discover:'Exploration request',craft:'Workshop request'};
const pic=k=>gameIcon(itemIcons[k]||k),count=k=>k==='marks'?state.frontier.marks:k in state.life?state.life[k]:state[k]||0;
const chip=(k,n,have)=>`<span class="ingredient ${have!==undefined&&have<n?'missing':''}">${pic(k)}<b>${have===undefined?n:Math.min(have,n)+' / '+n}</b><small>${itemNames[k]||k}</small></span>`;
const tabs=(items,current,group)=>`<div class="panel-tabs">${items.map(([id,name])=>`<button data-front="tab" data-group="${group}" data-id="${id}" aria-pressed="${current===id}">${name}</button>`).join('')}</div>`;
let bagTab='all',taskTab='story',friendTab='friends',selectedFriend='Emberkin';
function panel(title,body,kicker,section){show(title,body,kicker);document.querySelector('.dialog').classList.add('visual-panel');document.querySelector('.dialog').dataset.panel=section||'';}
function portraits(){for(const c of document.querySelectorAll('[data-friend-art]')){const n=c.dataset.friendArt,g=c.getContext('2d');g.imageSmoothingEnabled=false;g.drawImage(ValleyArt.make('friend-'+n+'-0',a=>ValleyArt.creatureSprite(a,n,0)),0,0);}}
bag=function(){accrue();const inventory=bagTab==='garden'?['turnips','moonbeans','seeds','moonSeeds','treats']:bagTab==='gear'?['tools','lantern']:['berries','wood','fish','crystals','herbs','ore','shells','marks'];panel('Inventory',`${tabs([['all','Materials'],['garden','Garden'],['gear','Gear']],bagTab,'bag')}<div class="inventory-grid">${inventory.map(k=>`<button class="item-tile" data-front="item" data-id="${k}">${pic(k)}<b>${shortCount(count(k))}</b><span>${itemNames[k]}</span></button>`).join('')}</div><div class="panel-footer"><div>${pic('bag')}<b>${bankTotal()}</b><span>supplies waiting</span></div><button data-ui="collect" ${bankTotal()<1?'disabled':''}>Collect all</button></div>`,'Your pack','bag');};
function itemPanel(k){const uses={herbs:'Gather in the orchard or marsh. Used in restoration projects and commissions.',ore:'Mine in the highlands. Used to repair the lift and observatory.',shells:'Collect along Tideglass Coast. Used for the observatory.',marks:'Earn through NPC commissions and companion expeditions. Spend on permanent restoration projects.',tools:'Adds one item to each completed gathering action.',lantern:'Lights the ground around you after sunset.',treats:'Feed to a companion for 50 bond XP.'};panel(itemNames[k],`<div class="item-feature">${pic(k)}<b>${count(k)}</b></div><p>${uses[k]||'Gather, grow or craft this item. Use it in recipes, companion care and restoration projects.'}</p><div class="actions"><button data-front="bag">Back to inventory</button><button data-front="projects">Projects</button></div>`,'Item details');}
function rank(){return Math.min(10,1+Math.floor(state.frontier.completed/3));}
function requestCard(id){const r=F.regions[id],order=state.frontier.orders[id],visited=state.life.visits.includes(id),locked=!F.unlocked(state,id),progress=order?F.progress(state,id):[],kind=order?.kind||'gather',ready=order&&progress.every(p=>p.have===p.need)&&(kind!=='gather'||F.costs(state,F.needs(order,id)));return `<article class="request-card"><div class="request-heading">${gameIcon(r.icon)}<div><b>${r.npc}</b><small>${order?requestKindLabel[kind]:r.name}</small></div><span class="reward">${pic('marks')}3</span></div>${order?`<div class="ingredient-row">${progress.map(p=>chip(p.item,p.need,p.have)).join('')}</div><button data-front="deliver" data-id="${id}" ${ready?'':'disabled'}>${ready?'Deliver':kind==='farm'?'Grow and harvest more':kind==='craft'?'Craft more at the workbench':kind==='discover'?'Explore somewhere new':'Gather fresh supplies'}</button>`:`<div class="ingredient-row">${Object.entries(r.needs).map(([k,n])=>chip(k,n)).join('')}</div><button data-front="accept" data-id="${id}" ${locked||!visited?'disabled':''}>${locked?'Restore the route first':!visited?'Meet '+r.npc:'Accept request'}</button>`}</article>`;}
function projectCard(id){const p=F.projects[id],done=state.frontier.projects[id];return `<article class="project-card ${done?'finished':''}"><div class="request-heading">${gameIcon(p.icon)}<div><b>${p.name}</b><small>${F.regions[p.region].name}</small></div></div><p>${p.reward}</p>${done?'<span class="completion">'+gameIcon('check')+'Restored</span>':`<div class="ingredient-row">${Object.entries(p.cost).map(([k,n])=>chip(k,n,F.amount(state,k))).join('')}</div><button data-front="build" data-id="${id}" ${F.costs(state,p.cost)?'':'disabled'}>Restore</button>`}</article>`;}
adventureMenu=function(){const old=MossSystems.chapters.findIndex((_,i)=>!state.life.claimed.includes(i));let body='';if(taskTab==='story'){if(old>=0){const c=MossSystems.chapters[old];body=`<article class="story-feature">${gameIcon('tasks')}<small>CHAPTER ${old+1} / 8</small><h3>${c[0]}</h3><p>${c[1]}</p><button data-life="claim" data-id="${old}" ${c[2](state)?'':'disabled'}>${c[2](state)?'Collect '+c[3]+' coins':'In progress'}</button></article>`;}else{const next=Object.keys(F.projects).find(k=>!state.frontier.projects[k]);body=next?`<article class="story-feature">${gameIcon(F.projects[next].icon)}<small>THE FRONTIER · ${Object.values(state.frontier.projects).filter(Boolean).length} / 5 RESTORED</small><h3>${F.projects[next].name}</h3><p>${F.projects[next].reward}</p><button data-front="projects">View project</button></article>`:`<article class="story-feature">${gameIcon('check')}<h3>A thriving frontier</h3><p>All five landmarks restored. Keep building reputation through commissions and train your companions on expeditions.</p><button data-front="requests">New requests</button></article>`;}body+=`<details class="completed-history"><summary>${state.life.claimed.length} completed chapters</summary>${state.life.claimed.map(i=>`<p>✓ ${MossSystems.chapters[i][0]}</p>`).join('')}</details>`;}else if(taskTab==='requests')body=`<div class="reputation">${gameIcon('tasks')}<b>Trail rank ${rank()}</b><span>${state.frontier.completed} requests completed</span></div><p class="panel-note">Gather fresh supplies after accepting. Trail ranks 2 and 3 unlock longer expeditions.</p>${Object.keys(F.regions).map(requestCard).join('')}`;else body=Object.keys(F.projects).map(projectCard).join('');panel('Adventure',`${tabs([['story','Story'],['requests','Requests'],['projects','Projects']],taskTab,'tasks')}${body}`,'Your next step','tasks');};
companionMenu=function(){let body='';if(friendTab==='trips'){const eligible=state.team.filter(n=>n!==state.life.active&&!state.frontier.trips[n]);if(!eligible.includes(selectedFriend))selectedFriend=eligible[0];body=`<div class="trip-list">${Object.entries(state.frontier.trips).map(([n,t])=>{const seconds=Math.max(0,Math.ceil((t.start+t.duration*1000-Date.now())/1000));return `<article class="request-card"><div class="request-heading"><canvas data-friend-art="${n}" width="96" height="96"></canvas><div><b>${n}</b><small>${F.routes[t.duration].name}</small></div></div><p>${seconds?Math.ceil(seconds/60)+' min remaining':'Back with supplies'}</p><button data-front="tripclaim" data-name="${n}" ${seconds?'disabled':''}>Collect rewards</button></article>`;}).join('')}</div><div class="friend-picker">${eligible.map(n=>`<button data-front="tripfriend" data-name="${n}" aria-pressed="${selectedFriend===n}">${n}</button>`).join('')}</div>${selectedFriend?Object.entries(F.routes).map(([duration,r])=>`<article class="route-card">${gameIcon('map')}<div><b>${r.name}</b><small>${r.minutes} min · ${r.marks} trail marks · ${Object.entries(r.items).map(([k,v])=>v+' '+k).join(', ')}</small></div><button data-front="dispatch" data-duration="${duration}" ${state.berries<10||(Number(duration)===1200&&rank()<2)||(Number(duration)===3600&&rank()<3)?'disabled':''}>${Number(duration)===1200&&rank()<2?'Rank 2 required':Number(duration)===3600&&rank()<3?'Rank 3 required':'Send · 10 berries'}</button></article>`).join(''):'<p class="empty-panel">Choose a different travelling friend to free up a companion for an expedition.</p>'}<p class="panel-note">Away companions pause their normal gathering job. Completed expeditions wait safely for you.</p><button data-front="friends">Refresh return times</button>`;}else body=state.team.map(n=>{const trip=state.frontier.trips[n],level=MossSystems.level(state,n);return `<article class="friend-card"><div class="friend-portrait"><canvas data-friend-art="${n}" width="96" height="96"></canvas><span>LV ${level}</span></div><div class="friend-info"><h3>${n}</h3><small>${trip?'On expedition':state.life.active===n?'Travelling with you':'Working at camp'}</small><div class="health"><div style="width:${level===10?100:state.life.bond[n]%100}%"></div></div><p>${bondDescriptions[n]}</p>${friendTab==='jobs'?`<div class="job-options">${Object.keys(rates).map(k=>`<button data-front="job" data-name="${n}" data-id="${k}" aria-label="${names[k]} for ${n}" aria-pressed="${state.jobs[n]===k}" ${trip?'disabled':''}>${pic(k)}</button>`).join('')}</div><small>${trip?'Returns to this job after the expedition':Math.round(3600/rates[state.jobs[n]]*state.upgrade)+' supplies / hour'}</small>`:`<div class="actions"><button data-front="follow" data-name="${n}" ${trip||state.life.active===n?'disabled':''}>Travel</button><button data-front="feed" data-name="${n}" ${trip||state.life.treats<1||level===10?'disabled':''}>Treat · ${state.life.treats}</button></div>`}</div></article>`;}).join('');panel('Companions',`${tabs([['friends','Friends'],['jobs','Jobs'],['trips','Expeditions']],friendTab,'friends')}${body}`,'Better together','friends');portraits();};
upgradeDialog=function(){panel('Workshop',`<div class="recipe-grid">${Object.entries(MossSystems.recipes).map(([id,r])=>{const owned=['tools','lantern'].includes(r.item)&&state.life[r.item];return `<article class="recipe-card">${pic(r.item)}<b>${r.name}</b><div class="ingredient-row">${Object.entries(r.cost).map(([k,n])=>chip(k,n,k in state.life?state.life[k]:state[k])).join('')}</div><button data-front="craft" data-id="${id}" ${owned||!Object.entries(r.cost).every(([k,v])=>(k in state.life?state.life[k]:state[k])>=v)?'disabled':''}>${owned?'Owned':'Craft'}</button></article>`;}).join('')}</div><div class="panel-footer"><div><b>Camp ${state.upgrade}</b><span>${state.upgrade*10} wood + ${state.upgrade*50} coins</span></div><button data-ui="upgrade" ${state.wood<state.upgrade*10||state.coins<state.upgrade*50?'disabled':''}>Upgrade</button></div>`,'Recipes & equipment','workshop');};
const frontierNearest=nearest;nearest=function(){let best=frontierNearest(),dist=best?Math.hypot(best.x-player.x,best.y-player.y):43;for(const o of map.objects.filter(o=>['herb','ore','shell','trailboard','trailgate','landmark'].includes(o.type))){const d=Math.hypot(o.x-player.x,o.y-player.y);if(d<dist){best=o;dist=d;}}return best;};
const frontierInteract=interact;interact=function(){if(!dialog&&!activity){const o=nearest();if(o?.type==='trailgate'){taskTab='projects';adventureMenu();return;}if(o?.type==='trailboard'||o?.type==='landmark'){taskTab=o.type==='landmark'?'projects':'requests';adventureMenu();return;}if(o?.kind==='human'&&F.regions[map.id]){const r=F.regions[map.id];panel(r.npc,`<div class="npc-intro">${gameIcon(r.icon)}<div><b>${r.role}</b><p>“${r.line}”</p></div></div>${requestCard(map.id)}<div class="actions"><button data-front="projects">Restoration projects</button><button data-ui="close">See you soon</button></div>`,r.name,'npc');return;}}frontierInteract();};
const frontierComplete=completeActivity;completeActivity=function(){if(!activity)return;const item=resourceInfo[activity.o.type].item,before=state[item]||0;const bonus={ore:'lift',herbs:'boardwalk',fish:'harbour',crystals:'observatory'}[item];if(bonus&&state.frontier.projects[bonus])state[item]++;frontierComplete();state.frontier.gathered[item]=(state.frontier.gathered[item]||0)+Math.max(0,state[item]-before);save();};
const originalHarvest=MossSystems.harvest;MossSystems.harvest=function(s,id,now){const crop=s.life.plots[id]?.crop,ok=originalHarvest(s,id,now);if(ok&&s.frontier.projects.nursery)s.life[crop==='turnip'?'turnips':'moonbeans']++;return ok;};
// New NPCs follow their own regional routine; original villagers keep theirs.
const regionalTick=tickActivities;tickActivities=function(dt){const people=F.regions[map.id]?map.npcs:[];const original=map.npcs;if(people.length)map.npcs=original.filter(n=>n.kind!=='human');regionalTick(dt);map.npcs=original;for(const n of people.filter(n=>n.kind==='human'))if(!dialog&&Math.hypot(n.x-player.x,n.y-player.y)>58){const t=valleyTime(),tx=(t.night||t.rain?26:t.hour<12?24:20)*T+16,ty=(t.night||t.rain?23:17)*T+16;move(map,n,(tx-n.x)*dt*.35,(ty-n.y)*dt*.35);}};
function finish(message){FrontierWorld.apply(worlds,state.frontier.projects);save();hud();if(message){GameAudio.sfx('success');toast(message);}}
app.addEventListener('click',e=>{const b=e.target.closest('[data-front]');if(!b||b.disabled)return;const a=b.dataset.front,id=b.dataset.id,n=b.dataset.name;if(a==='tab'){if(b.dataset.group==='bag'){bagTab=id;bag();}else if(b.dataset.group==='tasks'){taskTab=id;adventureMenu();}else{friendTab=id;companionMenu();}return;}if(a==='bag'){bag();return;}if(a==='item'){itemPanel(id);return;}if(a==='requests'||a==='projects'){taskTab=a;adventureMenu();return;}if(a==='friends'){companionMenu();return;}if(a==='look'){appearance();return;}if(a==='tripfriend'){selectedFriend=n;companionMenu();return;}if(SaveStore.status().blocked){saveMenu();return;}
if(a==='accept'){if(F.accept(state,id))finish('Request accepted. Gather fresh supplies to fill it.');taskTab='requests';adventureMenu();}else if(a==='deliver'){if(F.deliver(state,id))finish('Delivered! +3 trail marks and reputation.');adventureMenu();}else if(a==='build'){if(F.build(state,id))finish(F.projects[id].name+' complete!');else toast('Finish the prerequisite route or gather the remaining materials.');adventureMenu();}else if(a==='dispatch'){accrue();if(F.dispatch(state,selectedFriend,Number(b.dataset.duration)))finish(selectedFriend+' has set off.');companionMenu();}else if(a==='tripclaim'){accrue();if(F.claimTrip(state,n))finish(n+' returned with supplies!');companionMenu();}else if(a==='follow'&&state.team.includes(n)&&!state.frontier.trips[n]){state.life.active=n;finish();companionMenu();}else if(a==='feed'&&state.team.includes(n)&&!state.frontier.trips[n]&&state.life.treats>0&&MossSystems.level(state,n)<10){state.life.treats--;state.life.bond[n]=Math.min(900,state.life.bond[n]+50);finish();companionMenu();}else if(a==='job'&&state.team.includes(n)&&rates[id]&&!state.frontier.trips[n]){accrue();state.jobs[n]=id;finish();companionMenu();}else if(a==='craft'&&map.id==='home'&&nearest()?.type==='workbench'){if(MossSystems.craft(state,id))finish('Crafted '+MossSystems.recipes[id].name);upgradeDialog();}else if(a==='avatar'){const k=b.dataset.kind,v=Number(id);if(['hair','coat'].includes(k)&&v>=0&&v<=3)state.frontier.avatar[k]=v;if(k==='hat')state.frontier.avatar.hat=!state.frontier.avatar.hat;finish();appearance();}});
const regionHud=hud;hud=function(){regionHud();if(GameAudio.setScene)GameAudio.setScene(map.id,valleyTime().night);const ready=Object.keys(state.frontier.orders).some(id=>F.progress(state,id).every(p=>p.have===p.need));if(ready)document.getElementById('task-ready').hidden=false;};
// Dock icons share a silhouette; selection follows the panel actually opened.
const panelShow=show;show=function(title,body,kicker){panelShow(title,body,kicker);document.querySelectorAll('.game-dock button').forEach(b=>b.classList.remove('selected'));const key=title==='Inventory'?'bag':title==='Companions'?'friends':title==='The frontier'?'map':title==='Your homestead'?'home':'menu';document.querySelector(`.game-dock [data-game="${key}"]`)?.classList.add('selected');};
const panelClose=close;close=function(){panelClose();document.querySelectorAll('.game-dock button').forEach(b=>b.classList.remove('selected'));};
const oldCamp=campPanel;campPanel=function(){oldCamp();const row=document.createElement('div');row.className='actions';row.innerHTML='<button data-front="projects">Restoration</button><button data-front="look">Appearance</button>';document.querySelector('.dialog').append(row);};
mapPanel=function(){const rows=[['grove','Moonleaf Grove','North from Willowmere'],['orchard','Bramble Orchard','West from Willowmere'],['highlands','Copper Highlands','North through the grove'],['marsh','Fernwater Marsh','West through the orchard'],['coast','Tideglass Coast','South from the riverbank'],['observatory','Starlight Plateau','North through the highlands']];panel('The frontier',`<div class="map-region-grid">${rows.map(([id,name,direction])=>`<article class="map-region ${map.id===id?'here':''}">${gameIcon(F.regions[id]?.icon||'map')}<b>${name}</b><small>${direction}</small><span>${!F.unlocked(state,id)?'Route needs restoration':map.id===id?'You are here':state.life.visits.includes(id)?'Explored':'Undiscovered'}</span></article>`).join('')}</div><div class="actions"><button data-extra="journal">Original valley trails</button><button data-front="projects">Unlock routes</button></div>`,'13 connected areas','map');};
const coats=['#478a82','#a46656','#6479a0','#887394'],hairs=['#75523c','#3e4144','#b06b41','#c5bd9d'];
function travelerSprite(npc,dir,step){const avatar=state.frontier.avatar,region=Object.keys(F.regions).indexOf(map.id),coat=npc?['#ac788a','#6e945e','#a58159','#7e899d','#b48265','#788d9d'][Math.max(0,region+1)]:coats[avatar.coat],hair=npc?'#b4a48a':hairs[avatar.hair],hat=!npc&&avatar.hat;return ValleyArt.make(`traveler-${coat}-${hair}-${hat}-${dir}-${step}`,({r,oval,poly})=>{
oval(0,1,8,3,'#25463544');r(-5,-7+step,4,8,'#374a43');r(2,-7-step,4,8,'#374a43');r(-6,-1+step,5,3,'#71543d');r(2,-1-step,5,3,'#71543d');poly([[-6,-21],[6,-21],[8,-8],[-8,-8]],'#354a40');poly([[-5,-20],[5,-20],[6,-9],[-6,-9]],coat);r(-3,-19,2,9,'#b4c5ac');r(-8,-18-step,3,8,coat);r(6,-18+step,3,8,coat);r(-8,-11-step,3,3,'#e5b78b');r(6,-11+step,3,3,'#e5b78b');oval(0,-27,7,8,'#624a38');oval(0,-26,6,7,'#e8be94');r(-6,-33,12,4,hair);r(-7,-30,3,6,hair);r(5,-30,2,7,hair);
if(dir===3){oval(0,-28,6,7,hair);r(-3,-32,3,8,hair==='#3e4144'?'#63625d':'#aa8457');r(-5,-19,10,12,'#594f37');r(-4,-18,8,10,'#bc9b62');r(-3,-18,6,3,'#e5c98d');r(-1,-13,2,3,'#f3dda2');}else if(dir===0){r(-4,-27,2,2,'#35423b');r(3,-27,2,2,'#35423b');r(-1,-22,3,1,'#ab7860');r(-5,-21,10,3,'#dfbc79');r(-4,-32,8,3,hair);r(-4,-30,3,2,hair);}else{const side=dir===1?-1:1;r(side===-1?-7:6,-26,2,3,'#e8be94');r(side===-1?-4:3,-27,2,2,'#35423b');r(side===-1?3:-6,-31,3,10,hair);r(side===-1?5:-7,-18,3,9,'#bc9b62');r(-5,-21,10,2,'#dfbc79');}if(hat){r(-9,-34,18,3,'#5a6849');r(-6,-38,12,5,'#8caa78');r(-5,-38,9,1,'#c4cdaa');r(-6,-34,12,1,'#d9bd7a');}
});}
human=function(x,y,npc=false,dir=0,walk=0){const step=walk?Math.round(Math.sin(walk)*1.5):0;ctx.drawImage(travelerSprite(npc,dir,step),Math.round(x)-48,Math.round(y)-80);};
function appearance(){panel('Your traveller',`<canvas class="avatar-preview" id="traveller-preview" width="96" height="96" aria-label="Traveller appearance preview"></canvas><div class="appearance-row"><b>Hair</b>${hairs.map((c,i)=>`<button data-front="avatar" data-kind="hair" data-id="${i}" style="--swatch:${c}" class="swatch" aria-label="Hair colour ${i+1}" aria-pressed="${state.frontier.avatar.hair===i}"></button>`).join('')}</div><div class="appearance-row"><b>Coat</b>${coats.map((c,i)=>`<button data-front="avatar" data-kind="coat" data-id="${i}" style="--swatch:${c}" class="swatch" aria-label="Coat colour ${i+1}" aria-pressed="${state.frontier.avatar.coat===i}"></button>`).join('')}</div><div class="actions"><button data-front="avatar" data-kind="hat" data-id="0">Hat: ${state.frontier.avatar.hat?'on':'off'}</button><button data-ui="close">Ready to explore</button></div>`,'Make yourself at home','appearance');const g=document.getElementById('traveller-preview').getContext('2d');g.imageSmoothingEnabled=false;g.drawImage(travelerSprite(false,0,0),0,0);}
const regionalObject=object;object=function(o){const x=o.x,y=o.y;
if(['herb','ore','shell'].includes(o.type)){const cooling=(state.cooldowns[o.id]||0)>Date.now();ValleyArt.put('frontier-'+o.type+'-'+cooling,x,y,({r,oval,poly})=>{oval(0,2,14,4,'#28483744');if(o.type==='herb'){for(const dx of [-7,0,7]){r(dx,-12,2,15,'#426b40');if(!cooling){poly([[dx,-6],[dx-8,-13],[dx-7,-18],[dx-1,-15]],'#82a759');poly([[dx+1,-8],[dx+8,-16],[dx+10,-13],[dx+5,-6]],'#adc67c');r(dx-1,-20,4,4,'#d8c897');}}}else if(o.type==='ore'){poly([[-17,1],[-14,-15],[-5,-24],[10,-22],[18,-7],[12,5]],'#4b6260');poly([[-14,-9],[-5,-21],[9,-19],[13,-8],[-2,-4]],'#8a9c8c');for(const[dx,dy]of [[-9,-9],[2,-16],[9,-5]]){r(dx,dy,7,5,cooling?'#718273':'#c68d55');if(!cooling)r(dx+1,dy,3,2,'#f0c28a');}}else{for(const[dx,dy]of [[-9,-3],[4,0],[9,-12]]){oval(dx,dy,6,5,cooling?'#a69577':'#e4c5a2');r(dx-4,dy-3,8,2,'#f5e0ba');r(dx,dy-3,1,6,'#b89478');r(dx-3,dy-2,1,4,'#b89478');}}});return;}
if(o.type==='trailboard'){regionalObject({...o,type:'sign'});rr(x-9,y-25,16,12,'#f0ddb0');rr(x-6,y-22,9,1,'#8b7955');rr(x-6,y-19,6,1,'#8b7955');return;}
if(o.type==='trailgate'){if(F.unlocked(state,o.gate)){regionalObject({...o,type:'sign'});return;}for(const dx of [-18,15])rr(x+dx,y-20,4,27,'#795b3b');rr(x-20,y-14,40,6,'#bb8d50');rr(x-20,y-4,40,5,'#bda06a');text('Restore route',x,y-29,'#f6e6ac',8);return;}
if(o.type==='landmark'){const id={orchard:'nursery',highlands:'lift',marsh:'boardwalk',coast:'harbour',observatory:'observatory'}[o.region],done=state.frontier.projects[id];rr(x-40,y-9,80,16,'#788b74');rr(x-35,y-11,70,8,'#b8b391');if(o.region==='orchard'){rr(x-28,y-50,56,42,'#735c3c');rr(x-25,y-47,50,36,done?'#a8cab0':'#647b67');for(let i=-25;i<25;i+=12)rr(x+i,y-47,3,36,'#dfc48a');for(let j=-46;j<-10;j+=12)rr(x-25,y+j,50,2,'#dfc48a');rr(x-31,y-54,62,5,done?'#559183':'#796d4a');for(let i=-25;i<25;i+=10){rr(x+i,y-5,8,6,'#9d774a');if(done){rr(x+i+2,y-13,3,10,'#78a653');rr(x+i,y-14,8,3,'#bdc779');}}}else if(o.region==='highlands'){rr(x-24,y-68,7,60,'#946a41');rr(x+19,y-68,7,60,'#946a41');rr(x-28,y-72,60,7,'#c09a59');rr(x+2,y-65,2,40,'#d0bd8a');rr(x-10,y-27,27,17,done?'#bcac70':'#766b51');rr(x-7,y-23,20,4,'#665b42');}else if(o.region==='observatory'){rr(x-21,y-53,42,44,'#718680');rr(x-25,y-58,50,8,done?'#518e8b':'#6a7669');rr(x-12,y-70,24,14,done?'#b8d0ba':'#899887');rr(x+8,y-76,24,9,done?'#d9ce94':'#8b907b');rr(x-5,y-31,11,22,'#405854');}else{for(let i=-35;i<35;i+=10)rr(x+i,y-25,8,30,done?'#c6a16b':'#7c7454');for(const dx of [-38,34]){rr(x+dx,y-40,5,41,'#8d6e46');rr(x+dx-2,y-43,9,4,'#dbc089');}if(done){rr(x-37,y-35,75,3,'#d5bd84');rr(x-37,y-10,75,3,'#d5bd84');}}if(done)text('Restored',x,y+23,'#eff3b9',9);return;}regionalObject(o);};
const regionalGround=ground;ground=function(x,y,t){regionalGround(x,y,t);if(!F.regions[map.id])return;if(['grass','tree','tall'].includes(t)){const p={orchard:'#739654',highlands:'#8a9b71',marsh:'#5d8a68',coast:'#a8af78',observatory:'#788f80'}[map.id];rr(x*T,y*T,T,T,p);const h=(x*73+y*47)%29;rr(x*T+h,y*T+9,2,3,'#b4c189');rr(x*T+8,y*T+h,3,1,'#557653');if(map.id==='orchard'&&h<3){rr(x*T+18,y*T+18,4,3,'#e4d395');rr(x*T+19,y*T+16,2,7,'#e4d395');}}};
hud();save();

audioMenu=function(){panel('Sound of the valley',`<div class="story-feature">${gameIcon('talk')}<h3>${GameAudio.track}</h3><small>FOUR ORIGINAL THEMES · CHANGING ARRANGEMENTS</small></div><div class="actions"><button data-extra="music">${GameAudio.settings.music?'Pause music':'Play music'}</button><button data-extra="effects">Effects: ${GameAudio.settings.effects?'on':'off'}</button></div><div class="panel-tabs"><button data-score="auto" aria-pressed="${GameAudio.settings.theme==='auto'}">Follow the world</button></div><div class="score-list">${GameAudio.themes.map(t=>`<button data-score="${t.id}" aria-pressed="${GameAudio.settings.theme===t.id}">${t.name}</button>`).join('')}</div><label class="volume-label">Music volume<input id="music-volume" type="range" min="0" max="100" value="${Math.round(GameAudio.settings.volume*100)}" aria-label="Music volume"></label><div class="actions"><button data-ambient="toggle">Ambience: ${GameAudio.settings.ambient?'on':'off'}</button></div><label class="volume-label">Ambience volume<input id="ambience-volume" type="range" min="0" max="100" value="${Math.round((GameAudio.settings.ambientVolume||0)*100)}" aria-label="Ambience volume"></label><p class="panel-note">Quiet passages between phrases. Automatic mode follows the area and rotates its arrangement.</p>`,'Music & effects','audio');};
app.addEventListener('click',e=>{const b=e.target.closest('[data-score]');if(b){GameAudio.setTheme(b.dataset.score);audioMenu();}});

app.addEventListener('click',async e=>{if(e.target.closest('[data-ambient]')){await GameAudio.unlock();GameAudio.setAmbient(!GameAudio.settings.ambient);audioMenu();}});app.addEventListener('input',e=>{if(e.target.id==='ambience-volume')GameAudio.setAmbientVolume(Number(e.target.value)/100);});
